                        )

        # Scan all configs
        for toml_path in (REGISTRY_DIR / "domains").glob("*.toml"):
            validate_file(toml_path, "domain")
        for toml_path in (REGISTRY_DIR / "tasks").glob("*.toml"):
            validate_file(toml_path, "task")
        for toml_path in (REGISTRY_DIR / "models").glob("*.toml"):
            validate_file(toml_path, "model")

        # Convert any accumulated lists to strings
        for key in list(results.keys()):
            if isinstance(results[key], list):
                results[key] = "; ".join(results[key])

        return results
